package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateUtils_isSameLocalTime_TriageGen0Test {

    @Test
    public void testIsSameLocalTime_NullFirstArgument() {
        try {
            DateUtils.isSameLocalTime(null, new GregorianCalendar());
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_NullSecondArgument() {
        try {
            DateUtils.isSameLocalTime(new GregorianCalendar(), null);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_IdenticalCalendars() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMillisecond() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.MILLISECOND, cal1.get(Calendar.MILLISECOND) + 1);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentSecond() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.SECOND, (cal1.get(Calendar.SECOND) + 1) % 60);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMinute() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.MINUTE, (cal1.get(Calendar.MINUTE) + 1) % 60);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentHour() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.HOUR, (cal1.get(Calendar.HOUR) + 1) % 24);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentDayOfYear() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.DAY_OF_YEAR, 1);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentYear() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.set(Calendar.YEAR, cal1.get(Calendar.YEAR) + 1);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentEra() {
        // Constructing different eras is tricky with standard Calendar, 
        // but we can simulate the logic by testing the equality check.
        // Since most modern calendars are ERA 1, we check the logic via equality.
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        // Manually forcing a difference if possible, otherwise testing logic coverage
        // Note: Era is usually handled by the year/century.
        // For coverage of the ERA field in the boolean expression:
        if (cal1.get(Calendar.ERA) != cal2.get(Calendar.ERA)) {
             assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
        } else {
             // If we can't easily change Era without complex setup, we rely on the fact
             // that the condition is part of the AND chain.
             assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
        }
    }

    @Test
    public void testIsSameLocalTime_DifferentClasses() {
        Calendar cal1 = new GregorianCalendar();
        // Using a different implementation of Calendar if possible, 
        // or just ensuring the class check is covered.
        // Since GregorianCalendar is the standard, we can't easily get another 
        // without mocking or a different JDK implementation. 
        // However, we can mock a subclass.
        class MockCalendar extends GregorianCalendar {}
        MockCalendar cal2 = new MockCalendar();

        // Reset values to be identical to cal1 to ensure it fails specifically on class check
        cal2.setTimeInMillis(cal1.getTimeInMillis());

        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }
}
